#!/usr/bin/env python3
"""Keep the frozen wormhole pole failure separate from exact-solution controls."""
import argparse,json,hashlib
from pathlib import Path
import numpy as np
p=argparse.ArgumentParser();p.add_argument('directory',type=Path);a=p.parse_args();d=a.directory;out=json.loads((d/'probe.stdout').read_text());table=d/'hermite-poles.csv';table=table if table.exists() else table.with_suffix('.csv.gz');x=np.genfromtxt(table,delimiter=',',names=True);fields=['chi','Khat','Theta','alpha','Axx','Axy','Axz','Ayy','Ayz','Azz','LambdaX','LambdaY','LambdaZ'];out['reference_pole_threshold']=1e-7;out['original_pole_gate_passed']=out['original_pole']<=1e-7;out['Hermite_pole_gate_passed']=out['Hermite_pole']<=1e-7;out['Minkowski_control_passed']=out['Minkowski_stored_constant_jet']==0 and max(out[k] for k in ['Minkowski_tensor_pole','Minkowski_tensor_limit','Minkowski_clock_rate'])<=1e-12;out['component_maxima']={mode:{f:float(np.max(abs(x[mode+'_'+f]))) for f in fields} for mode in ['original','Hermite']};out['worst_Hermite_xyz']=[float(x[k][int(out['Hermite_row'])]) for k in ['x','y','z']];out['analysis_script_sha256']=hashlib.sha256(Path(__file__).read_bytes()).hexdigest();(d/'analysis.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({k:out[k] for k in ['Hermite_pole','Hermite_pole_gate_passed','Minkowski_control_passed','clock_tangent_gradient']}))
